NODE_PATH=$(npm root -g) node -e "
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto('http://localhost:5199/settings/admin');
  await page.waitForSelector('text=Elena Martinez');
  const btn = page.locator('tr', { hasText: 'Elena Martinez' }).locator('button');
  console.log('elena disabled:', await btn.isDisabled());
  console.log('title:', await btn.getAttribute('title'));

  const rajBtn = page.locator('tr', { hasText: 'Raj Patel' }).locator('button');
  console.log('raj disabled:', await rajBtn.isDisabled());
  await rajBtn.click();
  await page.waitForTimeout(600);
  await page.screenshot({ path: '/tmp/claude-1001/after-deactivate.png' });
  console.log('raj row now:', await page.locator('tr', { hasText: 'Raj Patel' }).innerText());
  await browser.close();
})();
"
